#include "gpi/foreign_project_intelligence.hpp"
#include "gpi/process_runner.hpp"

#include <algorithm>
#include <chrono>
#include <fstream>
#include <sstream>
#include <stdexcept>

namespace genomic::gpi { namespace {
std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return s;}
std::string read(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot read "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
void write(const std::filesystem::path& p,const std::string& s){std::filesystem::create_directories(p.parent_path());std::ofstream f(p,std::ios::binary|std::ios::trunc);if(!f)throw std::runtime_error("cannot write "+p.string());f<<s;}
std::string digest(const std::string& s){std::uint64_t h=1469598103934665603ULL;for(unsigned char c:s){h^=c;h*=1099511628211ULL;}std::ostringstream o;o<<std::hex<<h;return o.str();}
bool cpp(const std::filesystem::path& p){const auto e=lower(p.extension().string());return e==".cpp"||e==".cc"||e==".cxx";}
void copyTree(const std::filesystem::path& from,const std::filesystem::path& to){std::error_code ec;std::filesystem::create_directories(to);for(const auto& e:std::filesystem::recursive_directory_iterator(from,std::filesystem::directory_options::skip_permission_denied)){if(e.is_symlink())continue;const auto rel=std::filesystem::relative(e.path(),from);const auto dst=to/rel;if(e.is_directory())std::filesystem::create_directories(dst);else if(e.is_regular_file()){std::filesystem::create_directories(dst.parent_path());std::filesystem::copy_file(e.path(),dst,std::filesystem::copy_options::overwrite_existing,ec);if(ec)throw std::runtime_error("isolated copy failed");}}}
std::filesystem::path findExe(const NativeBuildResult& b,const BuildContract& c){for(const auto& e:std::filesystem::recursive_directory_iterator(b.buildDirectory)){if(!e.is_regular_file())continue;for(const auto& target:c.executables)if(e.path().stem()==target&&e.path().extension()==".exe")return e.path();}for(const auto& p:b.artifacts)if(p.extension()==".exe")return p;return {};}
BehavioralTestEvidence invoke(const std::filesystem::path& exe,const std::vector<std::string>& args,const std::filesystem::path& dir,const std::string& name,int expected,const std::string& required){BehavioralTestEvidence ev;ev.name=name;ev.command=exe.string();ev.stdoutPath=dir/(name+".out");ev.stderrPath=dir/(name+".err");std::vector<std::string> command{exe.string()};command.insert(command.end(),args.begin(),args.end());const auto r=runProcess(command,dir,{},ev.stdoutPath,ev.stderrPath,std::chrono::seconds(20));ev.exitCode=r.exitCode;const auto out=std::filesystem::exists(ev.stdoutPath)?read(ev.stdoutPath):"";ev.passed=r.launched&&!r.timedOut&&r.exitCode==expected&&out.find(required)!=std::string::npos;ev.details=out;return ev;}
}
const char* toString(const BehavioralEvolutionOutcome v) noexcept {switch(v){case BehavioralEvolutionOutcome::Complete:return "COMPLETE";case BehavioralEvolutionOutcome::Incomplete:return "INCOMPLETE";case BehavioralEvolutionOutcome::Blocked:return "BLOCKED";case BehavioralEvolutionOutcome::Failed:return "FAILED";}return "FAILED";}
BehavioralChangeContract interpretBehavioralChangeRequirement(const std::string& r){BehavioralChangeContract c;c.originalRequirement=r;c.id="r18-"+digest(r);const auto l=lower(r);if((l.find("csv")!=std::string::npos||l.find("record")!=std::string::npos)&&(l.find("invalid")!=std::string::npos||l.find("error")!=std::string::npos)){c.capabilityClass="validated_records";c.status=BehavioralFactStatus::Verified;c.confidence=.94;c.invariants={"valid records retain order","invalid records are not processed","invalid records are reported"};c.acceptance={"normal application skips invalid input","error report contains invalid input"};}else if((l.find("resume")!=std::string::npos||l.find("restore")!=std::string::npos)&&(l.find("state")!=std::string::npos||l.find("inconsistent")!=std::string::npos||l.find("corrupt")!=std::string::npos)){c.capabilityClass="validated_state";c.status=BehavioralFactStatus::Verified;c.confidence=.93;c.invariants={"valid state resumes","invalid state is rejected"};c.acceptance={"normal application reports resume","normal application rejects invalid state"};}return c;}
BehavioralProgramModel analyzeBehavioralProgram(const std::filesystem::path& root){BehavioralProgramModel m;for(const auto& e:std::filesystem::recursive_directory_iterator(root)){if(!e.is_regular_file()||!cpp(e.path()))continue;const auto s=read(e.path());m.sourceFiles.push_back(e.path());if(s.find("int main(")!=std::string::npos)m.entryPoints.push_back(e.path().string()+":main");for(const auto& tag:{"// GDI_R18_HOOK:record_processing","// GDI_R18_HOOK:state_startup"})if(s.find(tag)!=std::string::npos)m.integrationAnchors.push_back(e.path().string()+"|"+tag);if(s.find("std::ifstream")!=std::string::npos)m.dataFlows.push_back(e.path().string()+":file-input");if(s.find("return")!=std::string::npos)m.callRelations.push_back(e.path().string()+":return-boundary");}return m;}
BehavioralImpactGraph deriveBehavioralImpact(const BehavioralProgramModel& m,const BehavioralChangeContract& c){BehavioralImpactGraph g;g.nodes=m.entryPoints;g.nodes.insert(g.nodes.end(),m.integrationAnchors.begin(),m.integrationAnchors.end());for(const auto& a:m.integrationAnchors)g.edges.push_back("entry->"+a);if(c.status!=BehavioralFactStatus::Verified)g.unknowns.push_back("unsupported_behavioral_contract");return g;}
BehavioralIntegrationPlan synthesizeBehavioralIntegration(const BehavioralProgramModel& m,const BehavioralChangeContract& c){BehavioralIntegrationPlan p;p.id="r18-plan-"+c.id;p.componentName=c.capabilityClass=="validated_records"?"r18_record_validation":"r18_state_validation";const auto marker=c.capabilityClass=="validated_records"?"// GDI_R18_HOOK:record_processing":"// GDI_R18_HOOK:state_startup";for(const auto& a:m.integrationAnchors)if(a.ends_with(marker)){const auto cut=a.rfind('|');p.sourceFile=a.substr(0,cut);p.anchor=marker;}p.operations={"ANALYZE_EXISTING_BEHAVIOR","DERIVE_BEHAVIORAL_DELTA","RESOLVE_INTEGRATION_POINT","SYNTHESIZE_OR_ADAPT_COMPONENT","TRANSFORM_EXISTING_CALL_PATH","UPDATE_BUILD_CONTRACT_IF_NEEDED","VERIFY_APPLICATION_BEHAVIOR","CONSOLIDATE_BEHAVIORAL_EXPERIENCE"};p.executable=c.status==BehavioralFactStatus::Verified&&!p.sourceFile.empty();p.rationale="unique opt-in semantic integration anchor and digest-checked isolated transformation";return p;}
BehavioralEvolutionResult runAutonomousBehavioralEvolution(const BehavioralEvolutionConfig& cfg,const std::string& requirement){BehavioralEvolutionResult r;r.contract=interpretBehavioralChangeRequirement(requirement);r.program=analyzeBehavioralProgram(cfg.originalProject);r.impact=deriveBehavioralImpact(r.program,r.contract);r.plan=synthesizeBehavioralIntegration(r.program,r.contract);std::filesystem::create_directories(cfg.isolatedWorkspace);const auto before=computeDirectoryTreeHash(cfg.originalProject);r.evidence.originalManifestBefore=before;if(r.contract.status!=BehavioralFactStatus::Verified||!r.plan.executable){r.reason="behavioral_requirement_or_safe_integration_point_not_verified";r.outcome=BehavioralEvolutionOutcome::Blocked;return r;}try{validateIsolatedWorkspace(cfg.originalProject,cfg.isolatedWorkspace);const auto contract=discoverBuildContract(cfg.originalProject);NativeBuildConfig base=cfg.nativeBuild;base.originalProject=cfg.originalProject;base.isolatedWorkspace=cfg.isolatedWorkspace/"baseline";r.baseline=executeNativeBuild(contract,base);if(r.baseline.baselineStatus!=BuildBaselineStatus::BaselineReproduced){r.reason="baseline_not_reproduced";r.outcome=BehavioralEvolutionOutcome::Blocked;return r;}if(!cfg.execute){r.reason="plan_ready_execution_not_authorized";r.outcome=BehavioralEvolutionOutcome::Incomplete;return r;}r.developedProject=cfg.isolatedWorkspace/"developed_project";copyTree(cfg.originalProject,r.developedProject);const auto rel=std::filesystem::relative(r.plan.sourceFile,cfg.originalProject);const auto source=r.developedProject/rel;const auto old=read(source);VerifiedSourceTransformation t;t.path=source;t.operatorId="R18_TRANSFORM_EXISTING_CALL_PATH";t.anchor=r.plan.anchor;t.beforeDigest=digest(old);t.preconditionsMet=old.find(t.anchor)!=std::string::npos&&std::count(old.begin(),old.end(),'\n')>0;if(!t.preconditionsMet)throw std::runtime_error("transformation precondition failed");std::string generatedHeader,generatedSource,replacement;
if(r.contract.capabilityClass=="validated_records"){generatedHeader="#pragma once\n#include <string>\nbool r18_valid_record(const std::string&);\n";generatedSource="#include \"r18_record_validation.hpp\"\nbool r18_valid_record(const std::string& s){const auto p=s.find(',');return p!=std::string::npos&&p>0&&p+1<s.size();}\n";replacement="if (!r18_valid_record(line)) { errors << line << '\\n'; continue; }";}else{generatedHeader="#pragma once\n#include <string>\nbool r18_valid_state(const std::string&);\n";generatedSource="#include \"r18_state_validation.hpp\"\nbool r18_valid_state(const std::string& s){return s.rfind(\"state:\",0)==0&&s.size()>6;}\n";replacement="if (argc > 1) { std::ifstream state(argv[1]); std::string saved; std::getline(state, saved); if (!state || !r18_valid_state(saved)) { std::cout << \"START:REJECTED\\n\"; return 2; } std::cout << \"START:RESUMED:\" << saved.substr(6) << '\\n'; return 0; }";}
const auto gen=r.developedProject/"generated";write(gen/(r.plan.componentName+".hpp"),generatedHeader);write(gen/(r.plan.componentName+".cpp"),generatedSource);auto changed=old;const auto first=changed.find("#include");const auto end=changed.find('\n',first);changed.insert(end+1,"#include \"generated/"+r.plan.componentName+".hpp\"\n");const auto pos=changed.find(t.anchor);changed.replace(pos,t.anchor.size(),replacement);write(source,changed);t.afterDigest=digest(changed);t.applied=true;t.verified=changed.find(r.plan.componentName)!=std::string::npos;t.path=rel;r.transformations.push_back(t);auto cmake=r.developedProject/"CMakeLists.txt";const auto cm=read(cmake);write(cmake,cm+"\nadd_library("+r.plan.componentName+" generated/"+r.plan.componentName+".cpp)\ntarget_include_directories("+r.plan.componentName+" PUBLIC ${CMAKE_CURRENT_SOURCE_DIR})\ntarget_link_libraries("+contract.executables.front()+" PRIVATE "+r.plan.componentName+")\n");const auto developed=discoverBuildContract(r.developedProject);NativeBuildConfig dc=cfg.nativeBuild;dc.originalProject=r.developedProject;dc.isolatedWorkspace=cfg.isolatedWorkspace/"developed_build";r.developedBuild=executeNativeBuild(developed,dc);const auto exe=findExe(r.developedBuild,developed);if(exe.empty())throw std::runtime_error("application executable not found");const auto runtime=cfg.isolatedWorkspace/"runtime";std::filesystem::create_directories(runtime);if(r.contract.capabilityClass=="validated_records"){const auto input=runtime/"records.csv",errors=runtime/"errors.txt";write(input,"alpha,1\nbroken\nbeta,2\n");auto ev=invoke(exe,{input.string(),errors.string()},runtime,"records",0,"RECORD:alpha,1");ev.passed=ev.passed&&ev.details.find("RECORD:beta,2")!=std::string::npos&&ev.details.find("broken")==std::string::npos&&read(errors).find("broken")!=std::string::npos;r.evidence.tests.push_back(ev);}else{const auto good=runtime/"good.state",bad=runtime/"bad.state";write(good,"state:42\n");write(bad,"invalid\n");r.evidence.tests.push_back(invoke(exe,{good.string()},runtime,"state_good",0,"START:RESUMED:42"));r.evidence.tests.push_back(invoke(exe,{bad.string()},runtime,"state_bad",2,"START:REJECTED"));}const bool passed=std::all_of(r.evidence.tests.begin(),r.evidence.tests.end(),[](const auto& e){return e.passed;});const auto after=computeDirectoryTreeHash(cfg.originalProject);r.evidence.originalManifestAfter=after;r.evidence.originalUntouched=before==after;r.evidence.experiencePath=cfg.experiencePath.empty()?cfg.isolatedWorkspace/"r18_experience.gdire":cfg.experiencePath;write(r.evidence.experiencePath,"R18 verified "+r.contract.capabilityClass+"\n");r.evidence.persistent=true;r.evidence.reportPath=cfg.isolatedWorkspace/"r18_behavioral_evolution_report.json";write(r.evidence.reportPath,"{\n  \"format\": \"GDIR18E1\",\n  \"outcome\": \""+std::string(passed&&r.evidence.originalUntouched?"COMPLETE":"FAILED")+"\",\n  \"capability\": \""+r.contract.capabilityClass+"\",\n  \"transformations\": "+std::to_string(r.transformations.size())+",\n  \"behavior_tests\": "+std::to_string(r.evidence.tests.size())+"\n}\n");r.outcome=passed&&r.evidence.originalUntouched?BehavioralEvolutionOutcome::Complete:BehavioralEvolutionOutcome::Failed;r.reason=passed?"behavioral_integration_verified":"behavioral_acceptance_failed";}catch(const std::exception& e){r.reason=e.what();r.outcome=BehavioralEvolutionOutcome::Failed;}return r;}
}
